with products_by_supplier as (select supplier_id, count(case when category = 'Grocery' then 1 end) as grocery_count from products group by supplier_id) select suppliers.id, suppliers.rating, suppliers.country, products_by_supplier.grocery_count from suppliers left outer join products_by_supplier on suppliers.id = products_by_supplier.supplier_id where products_by_supplier.grocery_count >= 4 order by rating, suppliers.id desc;
